public SequenceAssetLoader(EditedMediaItemSequence sequence, boolean forceAudioTrack, AssetLoader.Factory assetLoaderFactory, Looper looper, Listener listener, Clock clock) {
  editedMediaItems = sequence.editedMediaItems;
  isLooping = sequence.isLooping;
  this.forceAudioTrack = forceAudioTrack;
  this.assetLoaderFactory = assetLoaderFactory;
  sequenceAssetLoaderListener = listener;
  handler = clock.createHandler(looper, null);
  sampleConsumersByTrackType = new HashMap<>();
  mediaItemChangedListenersByTrackType = new HashMap<>();
  processedInputsBuilder = new ImmutableList.Builder<>();
  nonEndedTracks = new AtomicInteger();
  isCurrentAssetFirstAsset = true;
  try {
    if (editedMediaItems.size() > 0) {
      @SuppressWarnings("nullness:argument.type.incompatible") AssetLoader currentAssetLoader = assetLoaderFactory.createAssetLoader(editedMediaItems.get(0), looper, this);
      this.currentAssetLoader = currentAssetLoader;
    } else {
      throw new IllegalStateException("editedMediaItems is empty");
    }
  } catch (IndexOutOfBoundsException e) {
    throw new RuntimeException("Attempted to access an empty editedMediaItems list", e);
  }
}
